std::vector<VideoResult> sortResults(const std::vector<VideoResult>& results, SortOrder order) {
  std::vector<VideoResult> sortedResults = results;
  bool swapped;
  do {
    swapped = false;
    for (size_t i = 0; i < sortedResults.size() - 1; ++i) {
      if (order == SortOrder::Length) {
        if (sortedResults[i].length > sortedResults[i + 1].length) {
          std::swap(sortedResults[i], sortedResults[i + 1]);
          swapped = true;
        }
      } else if (order == SortOrder::Date) {
        if (sortedResults[i].date > sortedResults[i + 1].date) {
          std::swap(sortedResults[i], sortedResults[i + 1]);
          swapped = true;
        }
      } else if (order == SortOrder::Alphabetical) {
        if (sortedResults[i].name > sortedResults[i + 1].name) {
          std::swap(sortedResults[i], sortedResults[i + 1]);
          swapped = true;
        }
      }
    }
  } while (swapped);
  return sortedResults;
}

