    if (line.find("temperature_range") != std::string::npos) {
      size_t start = line.find("=") + 1;
      size_t end = line.find(",");
      range.first = std::stoi(line.substr(start, end - start));
      start = end + 2;
      end = line.find("\n");
      range.second = std::stoi(line.substr(start, end - start));
      break;
    }
  }
  return range;
}

