bool validate_input(const input_data& data) {
  bool isValid = true;

  // Check if input data is not null or empty
  if (!data) {
    isValid = false;
    data.reasoning = "Input data is null or empty";
  }

  // Validate voucher data if applicable
  if (data.type == input_type::VOUCHER) {
    if (!data.voucher_data) {
      isValid = false;
      data.reasoning = "Voucher data is null or empty";
    }
  }

  // Validate claim data if applicable
  if (data.type == input_type::CLAIM) {
    if (!data.claim_data) {
      isValid = false;
      data.reasoning = "Claim data is null or empty";
    }
  }

  // Validate report type if applicable
  if (data.type == input_type::REPORT) {
    if (data.report_type == report_type::UNKNOWN) {
      isValid = false;
      data.reasoning = "Unknown report type";
    }
  }

  return isValid;
}

