bool validateClaim(int claimID, const Claim& claim) {
  // Check if the claim has a diagnosis
  if (claim.diagnosis.empty()) {
    return false;
  }

  // Check if the claim has at least one lab test
  if (claim.labTests.empty()) {
    return false;
  }

  // Check if the claim has at least one drug
  if (claim.drugs.empty()) {
    return false;
  }

  // Check if the claim has a valid date
  if (claim.date.empty() || !isValidDate(claim.date)) {
    return false;
  }

  // Check if the claim has a valid amount
  if (claim.amount < 0) {
    return false;
  }

  // Check if the claim has a valid service provider ID
  if (claim.serviceProviderID < 0) {
    return false;
  }

  // If all checks pass, the claim is valid
  return true;
}

std::string generate_voucher_number(const std::string& project_code, const std::string& group_batch_code, const std::string& batch_number) {
  // Generate a unique voucher number using a secure random number generator
  std::random_device rd;
  std::mt19937 gen(rd());
  std::uniform_int_distribution<> dis(1000000000, 9999999999);
  std::string voucher_number = project_code + group_batch_code + batch_number + std::to_string(dis(gen));

  // Format the voucher number as a string with the required structure
  voucher_number = project_code + '-' + group_batch_code + '-' + batch_number + '-' + voucher_number;

  return voucher_number;
}

