    return "Invalid plugin name";
  }
  if (!validatePluginFeatures(pluginFeatures)) {
    return "Invalid plugin features";
  }
  std::string pluginCode = pluginName + "_";
  for (const auto& feature : pluginFeatures) {
    pluginCode += feature + ";";
  }
  return pluginCode;
}

